--Find customers who purchased products from the same category on at least three different dates

SELECT
    c.customerid,
    c.customername,
    p.category,
    COUNT(DISTINCT CAST(o.orderdate AS DATE)) AS PurchaseDays
FROM customer__ c
JOIN order__ o
    ON c.customerid = o.customerid
JOIN product__ p
    ON o.productid = p.productid
GROUP BY
    c.customerid,
    c.customername,
    p.category
HAVING COUNT(DISTINCT CAST(o.orderdate AS DATE)) >= 3;

--Calculate the percentage of total revenue generated by each employee in each month

WITH MonthlyEmployeeRevenue AS (
    SELECT
        e.employeeid,
        e.employeename,
        YEAR(o.orderdate) AS OrderYear,
        MONTH(o.orderdate) AS OrderMonth,
        SUM(o.quantity * p.price) AS Revenue
    FROM employee__ e
    JOIN order__ o
        ON e.employeeid = o.employeeid
    JOIN product__ p
        ON o.productid = p.productid
    GROUP BY
        e.employeeid,
        e.employeename,
        YEAR(o.orderdate),
        MONTH(o.orderdate)
)
SELECT
    employeeid,
    employeename,
    OrderYear,
    OrderMonth,
    Revenue,
    ROUND(
        100.0 * Revenue /
        NULLIF(
            SUM(Revenue) OVER (
                PARTITION BY OrderYear, OrderMonth
            ), 0
        ),
        2
    ) AS MonthlyRevenuePercentage
FROM MonthlyEmployeeRevenue
ORDER BY OrderYear, OrderMonth, Revenue DESC;